-- Set programs that you use
local terminal    = "kitty"
local fileManager = "dolphin"
local menu        = "fuzzel"
local liveWallpaper =
    "/home/3ty6six7/Pictures/Wallpapers/live/miyabi-looking-up-at-the-gray-sky-zenless-zone-zero-moewalls-com.mp4"
local toggleWaybarCmd = [[
    bash -lc '
        if pgrep -x waybar >/dev/null; then
            pkill -x waybar
        else
            waybar >/tmp/waybar.log 2>&1 &
        fi
    '
]]
local liveWallpaperCmd =
    'mpvpaper ALL "' .. liveWallpaper ..
    '" -o "no-audio loop-file=inf hwdec=auto"'
local systemDashboard = [[
    bash -lc '
        # Không dựng cây Dwindle trước khi Waybar reserve màn hình
        for i in $(seq 1 100); do
            if hyprctl layers -j | grep -qi "waybar"; then
                sleep 0.30
                break
            fi

            sleep 0.03
        done

        window_exists() {
            hyprctl clients -j |
                grep -q "\"class\": \"$1\""
        }

        wait_window() {
            class="$1"

            for i in $(seq 1 100); do
                window_exists "$class" && return 0
                sleep 0.02
            done

            return 1
        }

        focus_window() {
            class="$1"

            for i in $(seq 1 50); do
                hyprctl dispatch focuswindow "class:^${class}$" >/dev/null

                hyprctl activewindow -j |
                    grep -q "\"class\": \"${class}\"" &&
                    return 0

                sleep 0.02
            done

            return 1
        }

kitty --class sys-fastfetch --title Fastfetch \
    zsh -lc "clear; fastfetch; echo; ~/.config/hypr/scripts/sysinfo-panel.sh; exec zsh" &
    
        wait_window "sys-fastfetch"
        focus_window "sys-fastfetch"
        hyprctl dispatch layoutmsg "preselect r" >/dev/null

        kitty --class sys-yazi --title Yazi -e yazi &

        wait_window "sys-yazi"
        focus_window "sys-yazi"
        hyprctl dispatch layoutmsg "preselect d" >/dev/null

        kitty --class sys-peaclock --title Peaclock -e peaclock &

        wait_window "sys-peaclock"
        focus_window "sys-fastfetch"
    '
]]
    
