------ ANIMATION ------
-----------------------

-- 93-VS Motion Engine
-- Fast, restrained window motion + chainable workspace swipes.

-- Quick ease-out for windows and UI layers.
hl.curve("vs_snap", {
    type = "bezier",
    points = {
        { 0.16, 1.00 },
        { 0.30, 1.00 },
    },
})

-- Clean exit: leaves immediately without hanging on screen.
hl.curve("vs_exit", {
    type = "bezier",
    points = {
        { 0.40, 0.00 },
        { 1.00, 0.60 },
    },
})

-- Near-continuous swipe curve.
-- One shared curve for both directions prevents the start-stop feeling
-- when rapidly switching through several workspaces.
hl.curve("vs_swipe", {
    type = "bezier",
    points = {
        { 0.25, 0.72 },
        { 0.20, 1.00 },
    },
})

-- Subtle spring for opening and moving windows.
hl.curve("vs_fast", {
    type = "bezier",
    points = {
        { 0.20, 0.78 },
        { 0.28, 1.00 },
    },
})

-- Base fallback
hl.animation({
    leaf = "global",
    enabled = true,
    speed = 1.8,
    bezier = "vs_snap",
})

-- Windows ------------------------------------------------

hl.animation({
    leaf = "windows",
    enabled = true,
    speed = 1.55,
    bezier = "vs_fast",
    style = "popin 96%",
})

hl.animation({
