-- Workspaces -----------------------------------------------
-- Do not split normal workspaces into workspacesIn/Out.
-- Both sides inherit this exact motion, so repeated inputs retarget cleanly
-- and feel like one continuous horizontal swipe sequence.

hl.animation({
    leaf = "workspaces",
    enabled = true,
    speed = 1.35,
    bezier = "vs_swipe",
    style = "slidefadevert 26%",
})

-- Scratchpad / special workspace gets its own premium motion.
