    leaf = "specialWorkspace",
    enabled = true,
    speed = 1.5,
    bezier = "vs_fast",
    style = "slidefadevert 16%",
})

hl.animation({
    leaf = "specialWorkspaceOut",
    enabled = true,
    speed = 1.15,
    bezier = "vs_exit",
    style = "slidefadevert 12%",
})

